#!/usr/bin/env python3
"""Compute ground truth for CSX-220_Q1 from the local CSX-220 data files."""

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-220_Q1"
EVENT_ID = "CSX-220"
TARGET_FAMILY = "numeric_diagnosis"


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8"))


def extract_impact_footprint(extract: str) -> dict[str, int]:
    footprint_match = re.search(
        r"flow off area of\s*([0-9]+)\s*by\s*([0-9]+)\s*metres",
        extract,
        flags=re.IGNORECASE,
    )
    area_match = re.search(
        r"affected\s*([0-9]+)\s*hectares",
        extract,
        flags=re.IGNORECASE,
    )
    if not footprint_match or not area_match:
        raise ValueError("Could not extract expected impact-footprint values")
    return {
        "runout_width_m": int(footprint_match.group(1)),
        "runout_length_m": int(footprint_match.group(2)),
        "debris_flow_area_ha": int(area_match.group(1)),
    }


def round_float(value: float, digits: int) -> float:
    return round(float(value), digits)


def build_rubric() -> dict[str, Any]:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "output_schema_and_diagnosis_label",
                "points": 3,
                "description": (
                    "Returns the requested six-key JSON object with mechanism_label and diagnosis_label "
                    "matching the expected quick-clay, wet-context, radar-dominant diagnosis."
                ),
                "partial_credit": (
                    "Award 1-2 points for a valid but incomplete object or a generic landslide label."
                ),
            },
            {
                "name": "footprint_calculation",
                "points": 3,
                "description": (
                    "Reports 300 m width, 700 m length, 21.0 ha rectangular footprint proxy, and "
                    "9 ha debris-flow area."
                ),
                "partial_credit": (
                    "Award 1-2 points for correct source values with a missing or miscomputed "
                    "rectangle-area conversion."
                ),
            },
            {
                "name": "rainfall_ledger",
                "points": 4,
                "description": (
                    "Uses the 2020-12-26 through 2020-12-30 window and reports 72.2 mm total, "
                    "8.9 mm event-day precipitation, 14.44 mm/day wetness index, and 0.1233 "
                    "event-day fraction."
                ),
                "partial_credit": (
                    "Award 2-3 points for the correct window with minor rounding errors; award "
                    "1 point for using only the event-day value."
                ),
            },
            {
                "name": "change_signal_comparison",
                "points": 4,
                "description": (
                    "Reports 0.6378 radar, 0.3457 optical, 0.0912 coarse annual embedding context, "
                    "identifies radar_abs_mean as the dominant mean signal, and computes the 1.845 "
                    "radar-to-optical ratio."
                ),
                "partial_credit": (
                    "Award 2-3 points for identifying radar as largest with one missing value or "
                    "a minor ratio error; award 1 point for only naming the radar signal."
                ),
            },
            {
                "name": "exposure_context",
                "points": 2,
                "description": "Reports the rounded population value 1059042 and 1.059 million.",
                "partial_credit": "Award 1 point for one of the two population values or a small rounding mistake.",
            },
            {
                "name": "json_implied_formula_consistency",
                "points": 2,
                "description": (
                    "The returned JSON values are internally consistent with the area, wetness, event-day "
                    "fraction, and radar-to-optical formulas; no prose or formula strings outside the JSON are required."
                ),
                "partial_credit": "Award 1 point when most values are correct but one derived value is not formula-consistent.",
            },
            {
                "name": "overclaim_control",
                "points": 2,
                "description": (
                    "Avoids claiming rainfall proves the trigger or that population exposure is "
                    "confirmed loss."
                ),
                "partial_credit": (
                    "Award 1 point for one correct caution with another extra escalation."
                ),
            },
        ],
    }


def main() -> None:
    root = package_root()
    event = read_json(root, "metadata/event.json")

    wikipedia = read_json(root, "data/event_reports/event_reports_003_Wikipedia_2020_Gjerdrum_landslide.json")
    impact = extract_impact_footprint(wikipedia["extract"])
    rectangle_area_ha = impact["runout_width_m"] * impact["runout_length_m"] / 10000.0

    openmeteo = read_json(root, "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json")
    daily = openmeteo["daily"]
    precip_by_date = dict(zip(daily["time"], daily["precipitation_sum"]))
    antecedent_dates = ["2020-12-26", "2020-12-27", "2020-12-28", "2020-12-29", "2020-12-30"]
    daily_precip = {date: float(precip_by_date[date]) for date in antecedent_dates}
    antecedent_5_day = sum(daily_precip.values())
    event_day_precip = daily_precip["2020-12-30"]

    sentinel1 = read_json(root, "data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json")
    sentinel2 = read_json(root, "data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json")
    alphaearth = read_json(root, "data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    radar_abs = abs(float(sentinel1["stats"]["s1_vv_post_minus_pre_db_mean"]))
    optical_abs = abs(float(sentinel2["stats"]["sentinel2_dnbr_mean"]))
    embedding_mean = float(alphaearth["stats"]["alphaearth_1_minus_cosine_mean"])
    mean_change_values = {
        "radar_abs_mean": round_float(radar_abs, 4),
        "optical_abs_mean": round_float(optical_abs, 4),
        "embedding_mean": round_float(embedding_mean, 4),
    }
    dominant_signal = max(mean_change_values, key=lambda key: mean_change_values[key])

    worldpop = read_json(root, "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json")
    population_sum = round(worldpop["population_sum"]["population"])

    structured_answer = {
        "mechanism_label": "quick_clay_landslide",
        "footprint": {
            "runout_width_m": impact["runout_width_m"],
            "runout_length_m": impact["runout_length_m"],
            "rectangle_area_ha": round_float(rectangle_area_ha, 1),
            "debris_flow_area_ha": impact["debris_flow_area_ha"],
        },
        "rainfall": {
            "antecedent_5_day_precip_mm": round_float(antecedent_5_day, 1),
            "event_day_precip_mm": round_float(event_day_precip, 1),
            "wetness_index_mm_day": round_float(antecedent_5_day / 5.0, 2),
            "event_day_fraction": round_float(event_day_precip / antecedent_5_day, 4),
        },
        "change_signal": {
            **mean_change_values,
            "dominant_mean_signal": dominant_signal,
            "radar_to_optical_ratio": round_float(radar_abs / optical_abs, 3),
        },
        "exposure_context": {
            "population_sum_rounded": population_sum,
            "population_millions": round_float(population_sum / 1_000_000.0, 3),
        },
        "diagnosis_label": "large_quick_clay_footprint_wet_context_radar_dominant",
    }

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": structured_answer,
        "judge_anchors": {
            "target_family": TARGET_FAMILY,
            "answer": structured_answer["diagnosis_label"],
            "tolerances": {
                "rain_mm": 0.05,
                "wetness": 0.005,
                "fraction": 0.00005,
                "change": 0.00005,
                "ratio": 0.0005,
                "population_millions": 0.0005,
            },
            "required_claims": [
                "rainfall_context_not_trigger_proof",
                "population_context_not_loss",
                "annual_embedding_context_not_event_timed_proof",
            ],
        },
        "key_values": {
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "region": event["region"],
            "event_date": "2020-12-30",
            "target_family": TARGET_FAMILY,
            "daily_precip_mm": daily_precip,
            "formulae": {
                "rectangle_area_ha": "runout_width_m * runout_length_m / 10000",
                "wetness_index_mm_day": "antecedent_5_day_precip_mm / 5",
                "event_day_fraction": "event_day_precip_mm / antecedent_5_day_precip_mm",
                "radar_to_optical_ratio": "radar_abs_mean / optical_abs_mean",
            },
            "signal_scope": {
                "embedding_mean_scope": "coarse annual surface-change context; included in magnitude comparison but not treated as event-timed proof",
                "dominant_signal_rule": "largest of radar_abs_mean, optical_abs_mean, and embedding_mean",
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_003_Wikipedia_2020_Gjerdrum_landslide.json",
                "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
                "data/remote_sensing/remote_sensing_005_Sentinel-1_GRD_VV_pre_post_change.json",
                "data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json",
                "data/remote_sensing/remote_sensing_004_Google_Satellite_Embedding_annual_cosine-change_stats.json",
                "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json",
            ],
            "notes": "The embedding mean is a coarse annual context value; radar dominance and rainfall/population cautions are scored through the requested JSON fields and judge anchors.",
        },
    }

    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
